    constructor() {
        this.modal = document.getElementById('delete-modal');
        this.modalOverlay = this.modal.querySelector('.modal-overlay');
        this.modalClose = this.modal.querySelector('.modal-close');
        this.cancelBtn = document.getElementById('cancel-btn');
        this.confirmDeleteBtn = document.getElementById('confirm-delete-btn');
        this.deleteTriggers = document.querySelectorAll('.trigger.delete-btn');

        this.currentImageId = null;
        this.currentButton = null;

        this.init();
    }

    init() {
        // Add event listeners to all delete buttons
        this.deleteTriggers.forEach(button => {
            button.addEventListener('click', (e) => this.openModal(e));
        });

        // Add event listeners to modal controls
        this.modalClose.addEventListener('click', () => this.closeModal());
        this.modalOverlay.addEventListener('click', () => this.closeModal());
        this.cancelBtn.addEventListener('click', () => this.closeModal());
        this.confirmDeleteBtn.addEventListener('click', () => this.handleDelete());

        // Handle escape key to close modal
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape' && this.modal.classList.contains('active')) {
                this.closeModal();
            }
        });
    }

    openModal(e) {
        e.preventDefault();
        this.currentButton = e.target;
        this.currentImageId = this.currentButton.getAttribute('data-image-id');
        this.modal.classList.add('active');
        this.confirmDeleteBtn.focus();
    }

    closeModal() {
        this.modal.classList.remove('active');
        this.currentImageId = null;
        this.currentButton = null;
    }

    handleDelete() {
        if (this.currentImageId) {
            // Simulate delete action
            const imageCard = this.currentButton.closest('.image-card');
            if (imageCard) {
                // Add fade out animation
                imageCard.style.opacity = '0';
                imageCard.style.transform = 'scale(0.95)';
                setTimeout(() => {
                    imageCard.remove();
                    this.closeModal();
                }, 300);
            }
        }
    }
}

// Initialize app when DOM is ready
document.addEventListener('DOMContentLoaded', () => {
    new ImageLibraryApp();
});
