    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.3s ease;
}

.image-card:hover .image-container img {
    transform: scale(1.05);
}

.image-footer {
    padding: 1.5rem;
}

.image-footer h3 {
    font-size: 1.125rem;
    font-weight: 600;
